class Solution {
public:
    vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {
        vector<pair<int, int>> events;
        events.reserve(buildings.size() * 2);
        for (auto& b : buildings) {
            events.push_back({b[0], -b[2]});  // start: negative height
            events.push_back({b[1],  b[2]});  // end:   positive height
        }
        sort(events.begin(), events.end());

        multiset<int> heights;
        heights.insert(0);  // ground sentinel
        int prevMax = 0;
        vector<vector<int>> result;

        for (auto& e : events) {
            int x = e.first;
            int h = e.second;
            if (h < 0) {
                heights.insert(-h);
            } else {
                heights.erase(heights.find(h));
            }
            int currMax = *heights.rbegin();
            if (currMax != prevMax) {
                result.push_back({x, currMax});
                prevMax = currMax;
            }
        }

        return result;
    }
};
